insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$la-cocina-dona-marisol-sample$tt$, 'family', $tt$The Family$tt$, array[$tt$Marisol Vega-Ortiz began cooking for neighbors out of her apartment kitchen, one pot of mole at a time. When the line outside her door grew longer than her hallway, her son found a storefront two blocks away.$tt$, $tt$Today her granddaughter runs the front of the house and keeps Marisol's handwritten recipe cards in a battered tin beside the register. Regulars are welcome to ask to see them.$tt$]::text[], 1)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$la-cocina-dona-marisol-sample$tt$, 'food', $tt$The Food$tt$, array[$tt$The mole rojo takes two days. Dried chiles are toasted, soaked, and ground with seeds, bread, and a little chocolate, then simmered until it clings to the back of a spoon.$tt$, $tt$The family says the recipe came from Marisol's mother and has barely changed. The tortillas are pressed by hand each morning, and the kitchen runs out of mole before it runs out of anything else.$tt$]::text[], 2)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$la-cocina-dona-marisol-sample$tt$, 'building', $tt$The Building$tt$, array[$tt$A narrow brick storefront with a pressed-tin ceiling the family restored themselves, one panel at a time. The kitchen sits where the building's original bakery oven once stood.$tt$]::text[], 3)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$la-cocina-dona-marisol-sample$tt$, 'neighborhood', $tt$The Neighborhood$tt$, array[$tt$The blocks around the restaurant carry layers: church towers built by earlier immigrant communities, murals on brick walls, and families who have stayed for decades. The restaurant is a short walk from the parish hall where its first customers came after Sunday services.$tt$]::text[], 4)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
delete from public.place_sources where place_id = $tt$la-cocina-dona-marisol-sample$tt$;
insert into public.place_sources (place_id, label, kind, note, sort_order) values ($tt$la-cocina-dona-marisol-sample$tt$, $tt$Conversation with the owner's granddaughter (sample)$tt$, 'owner-interview', $tt$Recipe origin and family timeline.$tt$, 1);
insert into public.place_sources (place_id, label, kind, note, sort_order) values ($tt$la-cocina-dona-marisol-sample$tt$, $tt$Neighborhood Oral History Collection (sample)$tt$, 'oral-history', $tt$Used to check dates and the parish hall detail.$tt$, 2);

