insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$pan-dulce-aurora-sample$tt$, 'family', $tt$The Family$tt$, array[$tt$Rafael and Tomás Aguilar took over the bakery from their father, who first baked bread for the early shift workers on the block. The brothers split the night: Rafael mixes dough at two in the morning, Tomás handles the display and the regulars.$tt$]::text[], 1)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$pan-dulce-aurora-sample$tt$, 'food', $tt$The Food$tt$, array[$tt$Conchas are the headline, with a crackled sugar shell that the brothers press with a carved wooden stamp. The recipe uses a slow overnight rise, which gives the bread its tender, slightly tangy crumb.$tt$, $tt$On weekends the bakery makes pan de muerto in the weeks leading up to the autumn holiday, and neighbors start asking about it in September.$tt$]::text[], 2)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$pan-dulce-aurora-sample$tt$, 'neighborhood', $tt$The Neighborhood$tt$, array[$tt$The bakery is an early-morning landmark. Bus drivers, nurses coming off night shifts, and parents on the school run all pass through before eight, which is why the brothers keep the first batch at the front of the case.$tt$]::text[], 3)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
delete from public.place_sources where place_id = $tt$pan-dulce-aurora-sample$tt$;
insert into public.place_sources (place_id, label, kind, note, sort_order) values ($tt$pan-dulce-aurora-sample$tt$, $tt$Interview with Tomás Aguilar (sample)$tt$, 'owner-interview', $tt$All family and recipe details are as told by the owner.$tt$, 1);

