insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$cafe-tinta-sample$tt$, 'food', $tt$The Food$tt$, array[$tt$The menu is small and seasonal: pastries from nearby bakeries, simple sandwiches, and espresso drinks named after typefaces. The most requested item is a cardamom bun that rotates in and out with the weather.$tt$]::text[], 1)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$cafe-tinta-sample$tt$, 'building', $tt$The Building$tt$, array[$tt$The building was a neighborhood print shop for most of the last century, producing church bulletins, union flyers, and wedding invitations. When the shop closed, the new owners kept two iron presses in the front window and left the ink-stained floorboards as they were.$tt$, $tt$Look up: the skylight was installed so typesetters could work by daylight.$tt$]::text[], 2)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$cafe-tinta-sample$tt$, 'neighborhood', $tt$The Neighborhood$tt$, array[$tt$Printing was once a major trade in the neighborhood, and the café keeps a shelf of old posters from local events. Community groups still meet at the long table in the back.$tt$]::text[], 3)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
