insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$golden-ladle-noodle-house-sample$tt$, 'food', $tt$The Food$tt$, array[$tt$The congee simmers for six hours with rice, dried scallop, and ginger, and arrives at the table with a spread of toppings: fried dough, scallions, and thousand-year egg for the adventurous.$tt$, $tt$The noodles are cut to order. The kitchen says the trick is the rest between kneading and cutting.$tt$]::text[], 2)
