insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$sweet-peach-supper-club-sample$tt$, 'family', $tt$The Family$tt$, array[$tt$The current owners are not the founding family. They bought the building after a long search for a place with enough room to host live music, and they credit the earlier tenants with leaving behind a stage, a coat-check window, and a guest book dating back decades.$tt$]::text[], 1)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$sweet-peach-supper-club-sample$tt$, 'food', $tt$The Food$tt$, array[$tt$The menu leans on dishes that were Sunday staples in the area: smothered pork chops, peach cobbler, and cornbread baked in cast iron. The kitchen works from period cookbooks and community recipe pamphlets, and notes the source on the back of the menu.$tt$]::text[], 2)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$sweet-peach-supper-club-sample$tt$, 'building', $tt$The Building$tt$, array[$tt$The ballroom on the second floor was built as a social hall in the early twentieth century and later hosted dances and club meetings. The owners restored the sprung dance floor and the original proscenium arch.$tt$, $tt$The coat-check window is still in use, and the guest book is kept behind the host stand.$tt$]::text[], 3)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$sweet-peach-supper-club-sample$tt$, 'neighborhood', $tt$The Neighborhood$tt$, array[$tt$The surrounding blocks carry a deep history of music, publishing, and Black-owned business. The supper club commissions a rotating local artist to hang work in the lobby each season.$tt$]::text[], 4)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
delete from public.place_sources where place_id = $tt$sweet-peach-supper-club-sample$tt$;
