insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$kafe-nordlys-sample$tt$, 'family', $tt$The Family$tt$, array[$tt$The Lindqvist family has baked in this neighborhood for three generations. The founder's recipe notebook is written in two languages, with Swedish notes crossed out and rewritten in English as the bakery grew.$tt$, $tt$A grandson now runs the ovens. He keeps the notebook locked in the back office, and he'll show it to anyone who asks nicely on a slow afternoon.$tt$]::text[], 1)
