  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$kafe-nordlys-sample$tt$, 'neighborhood', $tt$The Neighborhood$tt$, array[$tt$The neighborhood has a long Scandinavian heritage, and the bakery is one of several businesses that have kept customs alive through seasonal events, such as a light festival in the dead of winter.$tt$]::text[], 3)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
