insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$hearth-and-rail-tavern-sample$tt$, 'food', $tt$The Food$tt$, array[$tt$The kitchen cooks almost everything over a single oak-fired hearth. The tasting menu follows the seasons, and the printed menu notes which farm or foraging partner supplied each ingredient.$tt$, $tt$Dessert is served at the old ticket counter, now a small pastry bar.$tt$]::text[], 1)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$hearth-and-rail-tavern-sample$tt$, 'building', $tt$The Building$tt$, array[$tt$The building opened as a rail depot in the early twentieth century and later served as a freight office and a warehouse. The owners kept the arched windows, the iron roof trusses, and the original ticket counter, which now serves as a pastry bar.$tt$, $tt$A set of vintage station clocks hangs over the dining room, each stopped at a different hour.$tt$]::text[], 2)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$hearth-and-rail-tavern-sample$tt$, 'neighborhood', $tt$The Neighborhood$tt$, array[$tt$The restaurant sits along a rail corridor that once shaped the commercial life of the area. The surrounding blocks have since filled with galleries, bars, and small shops, and the staff will point out what each building used to be.$tt$]::text[], 3)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
delete from public.place_sources where place_id = $tt$hearth-and-rail-tavern-sample$tt$;
insert into public.place_sources (place_id, label, kind, note, sort_order) values ($tt$hearth-and-rail-tavern-sample$tt$, $tt$Rail Depots of the Northwest Side (sample)$tt$, 'book', $tt$Building history and original use.$tt$, 1);
insert into public.place_sources (place_id, label, kind, note, sort_order) values ($tt$hearth-and-rail-tavern-sample$tt$, $tt$City Landmarks Commission Summary (sample)$tt$, 'archive', null, 2);

