  array['generations-old', 'neighborhood-institution', 'family-owned']::public.story_tag[], $tt$A butcher counter and lunch room that has fed workers from the neighborhood for four generations.$tt$, 'both',
  $tt$The smoked kielbasa lunch plate$tt$, $tt$It is the first recipe the family ever sold, and still the one the line forms for.$tt$, array[$tt$What wood do you smoke the kielbasa over?$tt$, $tt$Which regular has been coming the longest?$tt$, $tt$What would the first Kowalczyk to hold this knife make of the shop today?$tt$]::text[],
