insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$stockyard-sausage-haus-sample$tt$, 'family', $tt$The Family$tt$, array[$tt$The Kowalczyk family started with a single butcher block and a recipe for smoked kielbasa. Four generations later, the shop still sells by the pound from the counter and serves lunch at long communal tables.$tt$]::text[], 1)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$stockyard-sausage-haus-sample$tt$, 'food', $tt$The Food$tt$, array[$tt$The sausages are smoked in-house over hardwood, and the lunch plate pairs them with sauerkraut, boiled potatoes, and sharp mustard. Fridays are for potato pancakes.$tt$]::text[], 2)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$stockyard-sausage-haus-sample$tt$, 'building', $tt$The Building$tt$, array[$tt$The shop occupies a low brick building that has been a butcher since long before the current owners. The old meat hooks still hang over the counter, and the original tile floor has been patched but never replaced.$tt$]::text[], 3)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$stockyard-sausage-haus-sample$tt$, 'neighborhood', $tt$The Neighborhood$tt$, array[$tt$The neighborhood grew up around nearby industry, and the shop opened early to feed workers coming off the night shift. Many customers still stop in on their way to work, and some remember when the line stretched around the block.$tt$]::text[], 4)
  on conflict (place_id, kind) do update set title = excluded.title, body = excluded.body, sort_order = excluded.sort_order;
delete from public.place_sources where place_id = $tt$stockyard-sausage-haus-sample$tt$;
