insert into public.place_sources (place_id, label, kind, note, sort_order) values ($tt$stockyard-sausage-haus-sample$tt$, $tt$Neighborhood Trade Index, 1930s edition (sample)$tt$, 'archive', $tt$Cross-checked the shop's early years.$tt$, 2);

