insert into public.place_sections (place_id, kind, title, body, sort_order) values ($tt$varenyky-corner-sample$tt$, 'family', $tt$The Family$tt$, array[$tt$Oksana Melnyk opened the shop after retiring from a long career as a school cook. Her daughter and granddaughter now fold dumplings alongside her in the front window, where passersby stop to watch.$tt$]::text[], 1)
